/* Flaynity local HLS.js bootstrap.
 * Loads the pinned HLS.js UMD build when the local WebView does not already provide Hls.
 * The application references this local asset so Sketchware can package it with the WebView.
 */
(function(){
  if (window.Hls) return;
  var s=document.createElement('script');
  s.src='https://cdn.jsdelivr.net/npm/hls.js@1.7.2/dist/hls.min.js';
  s.async=false;
  s.onload=function(){ window.dispatchEvent(new Event('flaynity-hls-ready')); };
  s.onerror=function(){ console.error('[Flaynity] HLS.js failed to load.'); };
  document.head.appendChild(s);
})();
